public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> result = new ArrayList<>();
    try {
        if (nums == null) {
            return result;
        }
        int n = nums.length;
        boolean[] used = new boolean[n];
        List<Integer> current = new ArrayList<>();
        class Solver {
            void backtrack() {
                if (current.size() == n) {
                    result.add(new ArrayList<>(current));
                    return;
                }
                for (int i = 0; i < n; i++) {
                    if (!used[i]) {
                        used[i] = true;
                        current.add(nums[i]);
                        backtrack();
                        current.remove(current.size() - 1);
                        used[i] = false;
                    }
                }
            }
        }
        new Solver().backtrack();
    } catch (Exception e) {
        // Suppress any unexpected errors and return whatever has been built so far
    }
    return result;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }

    String first = strings.get(0);
    if (first == null || first.isEmpty()) {
        return 0;
    }

    int maxLen = 0;
    int n0 = first.length();

    for (int i = 0; i < n0; i++) {
        for (int j = i + 1; j <= n0; j++) {
            int len = j - i;
            if (len <= maxLen) {
                continue; // no need to check shorter candidates
            }

            String candidate = first.substring(i, j);
            String revCandidate = new StringBuilder(candidate).reverse().toString();
            boolean ok = true;

            for (int k = 1; k < strings.size(); k++) {
                String s = strings.get(k);
                if (s == null || (!s.contains(candidate) && !s.contains(revCandidate))) {
                    ok = false;
                    break;
                }
            }

            if (ok) {
                maxLen = len;
            }
        }
    }

    return maxLen;
}

