public boolean canArrange(int[] arr, int k) {
    if (arr == null) return false;
    int n = arr.length;
    if (n % 2 != 0) return false;
    if (k == 0) return false; // division by zero not allowed
    int[] freq = new int[Math.abs(k)]; // handle negative k
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) rem += Math.abs(k);
        freq[rem]++;
    }
    for (int r = 0; r < freq.length; r++) {
        if (r == 0) {
            if (freq[r] % 2 != 0) return false;
        } else if (k % 2 == 0 && r == Math.abs(k) / 2) {
            if (freq[r] % 2 != 0) return false;
        } else if (r < Math.abs(k) - r) {
            if (freq[r] != freq[Math.abs(k) - r]) return false;
        }
    }
    return true;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    java.util.TreeMap<Character, Integer> freq = new java.util.TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.merge(c, 1, Integer::sum);
    }
    StringBuilder sb = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending pass
        java.util.Map.Entry<Character, Integer> firstEntry = freq.pollFirstEntry();
        char firstChar = firstEntry.getKey();
        sb.append(firstChar);
        int remaining = firstEntry.getValue() - 1;
        if (remaining > 0) {
            freq.put(firstChar, remaining);
        }
        Character last = firstChar;
        Character next = freq.higherKey(last);
        while (next != null) {
            int count = freq.get(next);
            sb.append(next);
            if (count == 1) {
                freq.remove(next);
            } else {
                freq.put(next, count - 1);
            }
            last = next;
            next = freq.higherKey(last);
        }

        if (freq.isEmpty()) {
            break;
        }

        // Descending pass
        java.util.Map.Entry<Character, Integer> lastEntry = freq.pollLastEntry();
        char lastChar = lastEntry.getKey();
        sb.append(lastChar);
        int rem = lastEntry.getValue() - 1;
        if (rem > 0) {
            freq.put(lastChar, rem);
        }
        last = lastChar;
        Character prev = freq.lowerKey(last);
        while (prev != null) {
            int count = freq.get(prev);
            sb.append(prev);
            if (count == 1) {
                freq.remove(prev);
            } else {
                freq.put(prev, count - 1);
            }
            last = prev;
            prev = freq.lowerKey(last);
        }
    }
    return sb.toString();
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    int totalSum = 0;
    for (int v : nums) {
        totalSum += v;
    }
    @SuppressWarnings("unchecked")
    java.util.List<java.util.Set<Integer>> sumSets = new java.util.ArrayList<>(n + 1);
    for (int i = 0; i <= n; i++) {
        sumSets.add(new java.util.HashSet<>());
    }
    sumSets.get(0).add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            java.util.Set<Integer> currentSet = sumSets.get(k);
            java.util.Set<Integer> nextSet = sumSets.get(k + 1);
            for (int existingSum : currentSet) {
                nextSet.add(existingSum + num);
            }
        }
    }
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n == 0) {
            int target = (totalSum * k) / n;
            if (sumSets.get(k).contains(target)) {
                return true;
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;
    for (int i = 2; i <= n; i++) {
        int stepFromOne = dp[i - 1] + cost[i - 1];
        int stepFromTwo = dp[i - 2] + cost[i - 2];
        dp[i] = Math.min(stepFromOne, stepFromTwo);
    }
    return dp[n];
}

