public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    if (k < 0) {
        throw new IllegalArgumentException("k must be non-negative");
    }
    int n = s.length();
    if (k == 0) {
        // Only the empty string exists, which is trivially a substring
        return true;
    }
    if (k > 20) {
        // 2^k would be too large for a boolean array; the problem constraints
        // usually restrict k <= 10, but defensively return false here
        return false;
    }
    int total = 1 << k; // 2^k
    if (n < total) {
        return false; // Not enough length to contain all possible codes
    }
    boolean[] seen = new boolean[total];
    int seenCount = 0;
    int mask = total - 1;
    int code = 0;
    for (int i = 0; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[code]) {
                seen[code] = true;
                seenCount++;
                if (seenCount == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

