public int minInsertions(String s) {
    if (s == null) {
        throw new IllegalArgumentException("Input string cannot be null");
    }
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch == '(') {
            balance++;
        } else if (ch == ')') {
            if (balance > 0) {
                balance--;
            } else {
                insertions++;
                // We pretend to add an opening bracket before this closing one
                // so that the closing bracket can match it.
                // No change to balance after this because we've effectively opened and closed it.
            }
        } else {
            throw new IllegalArgumentException("String contains invalid character: " + ch);
        }
    }
    // Any remaining unmatched opening brackets need closing brackets
    insertions += balance;
    return insertions;
}

public int minOperations(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }
    if (n % 2 == 0) {
        int half = n / 2;
        return half * half; // (n/2)^2
    } else {
        int a = (n - 1) / 2;
        int b = (n + 1) / 2;
        return a * b; // ((n-1)/2) * ((n+1)/2)
    }
}

