}

public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxCurrent = nums[0];
    int maxTill = nums[0];
    int minCurrent = nums[0];
    int minTill = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int value = nums[i];
        maxCurrent = Math.max(value, maxCurrent + value);
        maxTill = Math.max(maxTill, maxCurrent);
        minCurrent = Math.min(value, minCurrent + value);
        minTill = Math.min(minTill, minCurrent);
    }
    return Math.max(maxTill, Math.abs(minTill));
}

public int findMinFibonacciNumbers(int k) {
    if (k <= 0) {
        throw new IllegalArgumentException("k must be a positive integer");
    }
    // Generate Fibonacci numbers up to k
    int[] fib = new int[50]; // sufficient for k <= 1e9
    int len = 0;
    fib[len++] = 1; // F1
    fib[len++] = 1; // F2
    while (true) {
        int next = fib[len - 1] + fib[len - 2];
        if (next > k) {
            break;
        }
        fib[len++] = next;
    }
    // Greedy selection of largest Fibonacci numbers
    int count = 0;
    int remaining = k;
    for (int i = len - 1; i >= 0 && remaining > 0; i--) {
        if (fib[i] <= remaining) {
            remaining -= fib[i];
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) {
        return -1;
    }
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    for (int i = 1; (long) i * i <= n; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

public String makeGood(String s) {
    if (s == null) {
        return "";
    }
    StringBuilder stack = new StringBuilder();
    try {
        for (int i = 0; i < s.length(); i++) {
            char current = s.charAt(i);
            int size = stack.length();
            if (size > 0) {
                char top = stack.charAt(size - 1);
                if (current != top && Math.abs(current - top) == 32) {
                    stack.deleteCharAt(size - 1);
                    continue;
                }
            }
            stack.append(current);
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return the original string
        return s;
    }
    return stack.toString();
}

