public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        throw new IllegalArgumentException("Input array must not be null or empty");
    }
    int ones = 0;   // bits which have appeared once
    int twos = 0;   // bits which have appeared twice
    for (int num : nums) {
        // Update 'twos' with bits that have appeared twice
        twos |= ones & num;
        // Update 'ones' with bits that have appeared once
        ones ^= num;
        // Remove bits that have appeared three times
        int commonMask = ~(ones & twos);
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

public static java.util.List<Integer> findSteppingNumbers(int low, int high) {
    java.util.List<Integer> result = new java.util.ArrayList<>();
    if (low > high) return result;
    if (high < 0) return result;
    java.util.Queue<Long> queue = new java.util.LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;
        if (num >= low) {
            result.add((int) num);
        }
        if (num == 0) continue;
        int lastDigit = (int) (num % 10);
        if (lastDigit > 0) {
            long next = num * 10 + (lastDigit - 1);
            if (next <= high) queue.offer(next);
        }
        if (lastDigit < 9) {
            long next = num * 10 + (lastDigit + 1);
            if (next <= high) queue.offer(next);
        }
    }
    java.util.Collections.sort(result);
    return result;
}

