    while (n / (int)factor != 0) {
        int high = n / (int)(factor * 10);
        int cur = (n / (int)factor) % 10;
        int low = n % (int)factor;
        if (cur == 0) {
            count += (long)high * factor;
        } else if (cur == 1) {
            count += (long)high * factor + low + 1;
        } else {
            count += (long)(high + 1) * factor;
        }
        factor *= 10;
    }
    return (int)count;
}

public static boolean isPowerOfTwo(int n) {
    if (n <= 0) {
        return false;
    }
    // Using bitwise trick: a power of two has only one bit set
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    // Handle non-negative integers only; if negative, return 0 (or could throw exception)
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert = new int[m][n];
    int[][] diag = new int[m][n];
    int[][] adiag = new int[m][n];
    int maxLen = 0;

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j] = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                adiag[i][j] = (i > 0 && j < n - 1 ? adiag[i - 1][j + 1] : 0) + 1;
                int cellMax = Math.max(Math.max(horiz[i][j], vert[i][j]), Math.max(diag[i][j], adiag[i][j]));
                if (cellMax > maxLen) {
                    maxLen = cellMax;
                }
            } else {
                horiz[i][j] = 0;
                vert[i][j] = 0;
                diag[i][j] = 0;
                adiag[i][j] = 0;
            }
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    int absValue = Math.abs(n);
    String numStr = Integer.toString(absValue);
    int len = numStr.length();
    if (len <= 3) {
        return negative ? "-" + numStr : numStr;
    }
    int startIdx = len % 3 == 0 ? 3 : len % 3;
    StringBuilder sb = new StringBuilder();
    sb.append(numStr, 0, startIdx);
    int idx = startIdx;
    while (idx < len) {
        sb.append('.');
        sb.append(numStr, idx, idx + 3);
        idx += 3;
    }
    return negative ? "-" + sb.toString() : sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute whether sum of any two numbers is a perfect square
    boolean[][] isSquareSum = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int sum = A[i] + A[j];
            int root = (int) Math.sqrt(sum);
            isSquareSum[i][j] = root * root == sum;
        }
    }

    // Memoization table: memo[lastIndex][mask] = number of ways
    int fullMask = (1 << n) - 1;
    int[][] memo = new int[n][1 << n];
    for (int i = 0; i < n; i++) {
        java.util.Arrays.fill(memo[i], -1);
    }

    java.util.function.IntBinaryOperator dfs = new java.util.function.IntBinaryOperator() {
        @Override
        public int applyAsInt(int args) {
            throw new UnsupportedOperationException();
        }
    };

    // Recursive lambda using helper method reference
    java.util.function.BiFunction<Integer, Integer, Integer> dfsFunc = new java.util.function.BiFunction<Integer, Integer, Integer>() {
        @Override
        public Integer apply(Integer last, Integer mask) {
            if (mask == fullMask) {
                return 1;
            }
            if (memo[last][mask] != -1) {
                return memo[last][mask];
            }
            int count = 0;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0 && isSquareSum[last][next]) {
                    count += apply(next, mask | (1 << next));
                }
            }
            memo[last][mask] = count;
            return count;
        }
    };

    int total = 0;
    for (int i = 0; i < n; i++) {
        total += dfsFunc.apply(i, 1 << i);
    }
    return total;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int maxArea = 0;
    java.util.Stack<Integer> stack = new java.util.Stack<>();
    int n = heights.length;
    for (int i = 0; i < n; i++) {
        while (!stack.isEmpty() && heights[i] < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    while (!stack.isEmpty()) {
        int height = heights[stack.pop()];
        int width = stack.isEmpty() ? n : n - stack.peek() - 1;
        int area = height * width;
        if (area > maxArea) {
            maxArea = area;
        }
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0] == null || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    int totalDiagonals = m + n - 1;
    for (int d = 0; d < totalDiagonals; d++) {
        int startRow = Math.max(0, d - (n - 1));
        int endRow = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int i = endRow; i >= startRow; i--) {
                int j = d - i;
                result[index++] = mat[i][j];
            }
        } else {
            for (int i = startRow; i <= endRow; i++) {
                int j = d - i;
                result[index++] = mat[i][j];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }

    char[] digits = String.valueOf(n).toCharArray();
    int length = digits.length;

    // Step 1: Find the largest index i such that digits[i] < digits[i + 1]
    int i = length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        // Digits are in non-increasing order; no larger permutation exists
        return -1;
    }

    // Step 2: Find the largest index j > i such that digits[j] > digits[i]
    int j = length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Step 3: Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 4: Reverse the subarray from i+1 to the end
    int left = i + 1;
    int right = length - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer, checking for overflow
    try {
        long value = Long.parseLong(new String(digits));
        if (value > Integer.MAX_VALUE) {
            return -1;
        }
        return (int) value;
    } catch (NumberFormatException e) {
        // Should not occur, but return -1 for safety
        return -1;
    }
}

